#!/usr/bin/env python3
"""Verify production download UI controls stay stable during queue progress."""
from pathlib import Path
import argparse
import os
import subprocess
import tempfile

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('--extension-classes', required=True, type=Path,
                    help='ext-classes directory produced by tools/local_build.sh')
parser.add_argument('--android-jar', type=Path,
                    default=Path(os.environ.get('ANDROID_HOME', str(Path.home()/'Android/Sdk')))/'platforms/android-36/android.jar')
args = parser.parse_args()
assert args.extension_classes.is_dir(), args.extension_classes
assert args.android_jar.is_file(), args.android_jar
ROOT = Path(__file__).resolve().parent.parent
r = ROOT/'extensions/extension/src/main/java'
android = str(args.android_jar.resolve())
base = str(args.extension_classes.resolve())
workspace = tempfile.TemporaryDirectory(prefix='afterglow-download-ui-')
s = Path(workspace.name)
prod=[r/'app/afterglow/extension/ui'/n for n in ['DownloadProgressSheet.java','VaultActivity.java']]
p=subprocess.run(['javac','-encoding','UTF-8','-classpath',android+':'+base,'-d',str(s/'real')]+list(map(str,prod)),capture_output=True,text=True);print(p.stderr);p.check_returncode()
