files=[]
for name,body in stubs.items():
 p=s/'stubs'/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(body+'\n');files.append(p)
files += [r/'app/afterglow/extension/downloads'/n for n in ['DownloadRequest.java','DownloadJob.java','LibraryItem.java']]
